insert into makers (id, brand, craft, olive_green, tagline, bio, story, techniques, instagram, trusted, approved_count, published, gst_registered, hero_image_url) values ('11111111-1111-4111-8111-000000000001', 'Tathaastu', 'Hand-shaped soy wax florals', true, 'Where craftsmanship meets the art of gifting.', 'An Olive Green partner. Every Tathaastu piece supports war widows and army wives as they rebuild their lives and become financially independent.', 'Soy wax is shaped petal by petal into lotuses, peonies and sunflowers, then set in brass urlis, teapots and sculpted vessels.
insert into makers (id, brand, craft, olive_green, tagline, bio, story, techniques, instagram, trusted, approved_count, published, gst_registered, hero_image_url) values ('11111111-1111-4111-8111-000000000002', 'Mushhk', 'Botanical oils, mists and salts', false, 'Serenity in a bottle.', 'Mushhk believes beauty lives not in youth but in continuity, in caring for yourself as you are.', 'Its oils, mists, salts and scrubs are made for the ten quiet minutes at either end of a day.
insert into makers (id, brand, craft, olive_green, tagline, bio, story, techniques, instagram, trusted, approved_count, published, gst_registered, hero_image_url) values ('11111111-1111-4111-8111-000000000003', 'Svara', 'Alcohol-free fragrance', false, 'A fragrance you wear for how it makes you feel.', 'Svara sets Indian botanicals on a magnesium oil base, with no alcohol.', 'Each spray carries 9 mg of magnesium and settles into the skin as a small evening ritual.
insert into makers (id, brand, craft, olive_green, tagline, bio, story, techniques, instagram, trusted, approved_count, published, gst_registered, hero_image_url) values ('11111111-1111-4111-8111-000000000004', 'Anirveda', 'Ayurvedic skincare', false, 'Skincare that begins in the Indian kitchen and bathhouse.', 'Saffron, triphala and ubtan, kept in jars and bottles painted with peacocks and lotus blooms.', 'Anirveda draws on old Indian bath rituals: a bath ubtan, a kumkumadi face pack, a saffron face wash, a triphala night cream, oil pulling and a face mist.
